+// getLatestThreadMeta returns the thread ID and last user message from the Zed DB.
+// Returns empty strings on any error (best-effort).
+func getLatestThreadMeta() (threadID string, lastUserMsg string, msgCount int) {
+	dbPath, err := getZedDBPath()
+	if err != nil {
+		return "", "", 0
+	}
+	db, err := sql.Open("sqlite3", dbPath+"?mode=ro")
+	if err != nil {
+		return "", "", 0
+	}
+	defer db.Close()
+
+	t, rawData, err := fetchLatestThread(db)
+	if err != nil {
+		return "", "", 0
+	}
+
+	transcript, err := parseTranscript(rawData)
+	if err != nil {
+		return t.ID, "", 0
+	}
+
+	// Find the last user message
+	for i := len(transcript) - 1; i >= 0; i-- {
+		if transcript[i].Role == "user" && strings.TrimSpace(transcript[i].Content) != "" {
+			lastUserMsg = transcript[i].Content
+			break
+		}
+	}
+
+	// Truncate long prompts for the event payload
+	if len(lastUserMsg) > 500 {
+		lastUserMsg = lastUserMsg[:500] + "..."
+	}
+
+	return t.ID, lastUserMsg, len(transcript)
+}
