+
+	usage, ok := parsed["request_token_usage"].(map[string]interface{})
+	if !ok {
+		return nil
+	}
+
+	var inputTokens, outputTokens, cacheReadTokens, apiCallCount int
+	for _, reqRaw := range usage {
