		Timestamp string `json:"timestamp"`
		Author    string `json:"author"`
		Message   string `json:"message"`
	} `json:"commit"`
	FilesChanged []string      `json:"files_changed"`
	DiffStats    string        `json:"diff_stats"`
	Threads      []interface{} `json:"threads"`
