		fmt.Printf("- **Time:** %s\n", entry.Commit.Timestamp)
		fmt.Printf("- **Author:** %s\n", entry.Commit.Author)

		if len(entry.FilesChanged) > 0 {
			fmt.Printf("- **Files:** %s\n", strings.Join(entry.FilesChanged, ", "))
