			fmt.Println("\n### Associated Threads\n")
			for _, tRaw := range entry.Threads {
				t := tRaw.(map[string]interface{})
				fmt.Printf("**Thread:** %s (%v messages)\n", t["summary"], t["message_count"])
				if tokens, ok := t["tokens"].(map[string]interface{}); ok {
					fmt.Printf("**Tokens:** %v input, %v output, %v cache read, %v API calls\n",
						tokens["input_tokens"], tokens["output_tokens"],
						tokens["cache_read_tokens"], tokens["api_call_count"])
				}
				fmt.Println()
			}
		}
		fmt.Println()
	}

	if len(orphanThreads) > 0 {
		fmt.Println("## Research / Planning Threads (no associated commits)\n")
		for _, tRaw := range orphanThreads {
			t := tRaw.(map[string]interface{})
			fmt.Printf("- **%s** (%v messages, updated %s)\n", t["summary"], t["message_count"], t["updated_at"])
		}
	}
