+			SELECT id, summary, updated_at, data_type, data, folder_paths
+			FROM threads
+			WHERE folder_paths LIKE ?
+			ORDER BY updated_at DESC
+		`, "%"+repoRoot+"%")
+	} else {
+		rows, err = db.Query(`
+			SELECT id, summary, updated_at, data_type, data, folder_paths
+			FROM threads
+			ORDER BY updated_at DESC
+		`)
+	}
