+		threads = append(threads, ThreadWithData{
+			ID:               id,
+			Summary:          summary,
+			UpdatedAt:        updatedAt,
+			FolderPaths:      fp,
+			DecompressedData: rawData,
+		})
+	}
+
+	return threads, nil
+}
