 func TestParseTranscript_MultipleToolUses(t *testing.T) {
 	raw := `{
 		"messages": [
 			{"Agent": {"content": [
 				{"ToolUse": {"name": "read_file", "input": {"path": "a.go"}}},
 				{"Text": "Found it."},
 				{"ToolUse": {"name": "write_file", "input": {"path": "b.go", "content": "x"}}}
 			]}}
 		]
